		return
	}
	if _, err := lookPath("entire-brain"); err != nil {
		return
	}

	args := []string{
		"brain", "memory", "notify",
		"--event", "checkpoint",
		"--session", sessionID,
	}
	if branch != "" {
		args = append(args, "--branch", branch)
	}

	spawnDetached(repoRoot, args...)
}
