// notifyHostedFactsSync is a test seam over hostedFactsSyncAndPull.
var notifyHostedFactsSync = hostedFactsSyncAndPull

// memoryCheckpointWorkLaunch spawns `memory checkpoint-work` detached, the same
// shape as memoryWorkerLaunch: `memory notify` is a fast content-free hint and
// must never carry the checkpoint work (distill agent calls, hosted sync round
// trips) inline — a host adapter may invoke it synchronously. The child runs
// with the worker-origin environment so nothing it shells out to re-notifies.
// Injectable for tests; a launch failure never fails the host.
var memoryCheckpointWorkLaunch = func(repoDir, sessionID, branch string) error {
	exe, err := os.Executable()
	if err != nil {
		return err
	}
	args := []string{"memory", "checkpoint-work", "--session", sessionID}
	if branch != "" {
		args = append(args, "--branch", branch)
	}
	command := exec.Command(exe, args...)
	command.Dir = repoDir
	command.Env = memoryWorkerChildEnvironment(os.Environ(), repoDir)
	command.Stdout = nil
	command.Stderr = nil
	if err := command.Start(); err != nil {
		return err
	}
	// Reap like memoryWorkerLaunchAfter: Wait in a goroutine keeps the launch
	// non-blocking without leaving a <defunct> child for the parent's lifetime.
	go func() { _ = command.Wait() }()
	return nil
}

// newMemoryCheckpointWorkCommand is the detached half of the checkpoint hint:
// notify records the hint and spawns this verb; this verb does the throttled
// export + distill + hosted sync. Hidden — it is an internal dispatch target,
// not a user surface.
func newMemoryCheckpointWorkCommand(opts Options) *cobra.Command {
	var session, branch string
	cmd := &cobra.Command{
		Use:    "checkpoint-work",
		Hidden: true,
		Short:  "Run the throttled checkpoint-hint work (internal)",
		Args:   cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			storage, err := resolveSessionsBrain(cmd.Context(), opts)
			if err != nil {
				return err
			}
			repoDir, local, err := resolveLocalTargetRepoDir(cmd.Context(), opts.Runner, agentSurfaceTarget(opts, nil))
			if err != nil || !local {
				return nil // no local repo: silence, never an error
			}
			hostedSyncOnCheckpointHint(cmd.Context(), cmd.ErrOrStderr(), opts, repoDir, storage, strings.TrimSpace(session), strings.TrimSpace(branch))
			return nil
		},
	}
	cmd.Flags().StringVar(&session, "session", "", "Canonical session id")
	cmd.Flags().StringVar(&branch, "branch", "", "Captured branch when the host knows it")
	return cmd
}

