28	// notifyHostedFactsSync is a test seam over hostedFactsSyncAndPull.
29	var notifyHostedFactsSync = hostedFactsSyncAndPull
30	
31	// memoryCheckpointWorkLaunch spawns `memory checkpoint-work` detached, the same
32	// shape as memoryWorkerLaunch: `memory notify` is a fast content-free hint and
33	// must never carry the upload's network round trips inline — a host adapter
34	// may invoke it synchronously. The child runs with the worker-origin
35	// environment so nothing it shells out to re-notifies. Injectable for tests;
36	// a launch failure never fails the host.
37	var memoryCheckpointWorkLaunch = func(repoDir, branch string) error {
38		exe, err := os.Executable()
39		if err != nil {
40			return err
41		}
42		args := []string{"memory", "checkpoint-work"}
43		if branch != "" {
44			args = append(args, "--branch", branch)
45		}
46		command := exec.Command(exe, args...)
47		command.Dir = repoDir
48		command.Env = memoryWorkerChildEnvironment(os.Environ(), repoDir)
49		command.Stdout = nil
50		command.Stderr = nil
51		if err := command.Start(); err != nil {
52			return err
53		}
54		// Reap like memoryWorkerLaunchAfter: Wait in a goroutine keeps the launch
55		// non-blocking without leaving a <defunct> child for the parent's lifetime.
56		go func() { _ = command.Wait() }()
57		return nil
58	}
59	
60	// newMemoryCheckpointWorkCommand is the detached half of the checkpoint hint:
61	// notify records the hint and spawns this verb; this verb uploads the fact
62	// store, throttled. Hidden — it is an internal dispatch target, not a user
63	// surface.
64	func newMemoryCheckpointWorkCommand(opts Options) *cobra.Command {
65		var branch string
66		cmd := &cobra.Command{
67			Use:    "checkpoint-work",
68			Hidden: true,
69			Short:  "Upload the fact store for a checkpoint hint (internal)",
70			Args:   cobra.NoArgs,
71			RunE: func(cmd *cobra.Command, _ []string) error {
72				storage, err := resolveSessionsBrain(cmd.Context(), opts)
73				if err != nil {
74					return err
75				}
76				repoDir, local, err := resolveLocalTargetRepoDir(cmd.Context(), opts.Runner, agentSurfaceTarget(opts, nil))
77				if err != nil || !local {
78					return nil // no local repo: silence, never an error
79				}
80				hostedSyncOnCheckpointHint(cmd.Context(), cmd.ErrOrStderr(), opts, repoDir, storage, strings.TrimSpace(branch))
81				return nil
82			},
83		}
84		cmd.Flags().StringVar(&branch, "branch", "", "Captured branch when the host knows it")
85		return cmd
86	}
87	
88	type memoryNotifySyncMarker struct {
89		LastSyncAt time.Time `json:"last_sync_at"`
90	}
91	
92	// hostedSyncOnCheckpointHint uploads the fact store on a checkpoint hint: the
93	// hinted branch, then the default branch, throttled by a shared marker. It
94	// deliberately does NOT distill — the hint is an upload beat for facts that
95	// already exist. Fact creation stays on the session-end hook and the daemon
96	// tick until it moves into the memory worker with the session-end deprecation.
97	// The marker is claimed BEFORE the work so concurrent notify processes skip
98	// instead of stampeding; a failed run after the claim simply waits out the
99	// interval, which the never-fails contract already tolerates.
100	//
101	// Same contract as hostedFactsSyncAndPull: this runs behind a host lifecycle
102	// hint, so nothing here may fail the caller — every outcome is reported on
103	// errW and swallowed. The return value says whether the work ran, for tests
104	// and for the caller's log line only.
105	func hostedSyncOnCheckpointHint(ctx context.Context, errW io.Writer, opts Options, repoDir string, storage repoStorage, branch string) bool {
106		claimed := false
107		if err := withBrainWriteLock(storage.BrainDir, func() error {
108			now := opts.Now().UTC()
109			marker := readMemoryNotifySyncMarker(storage.BrainDir)
110			if now.Sub(marker.LastSyncAt) < memoryNotifyHostedSyncMinInterval {
111				return nil
112			}
113			if err := writeMemoryNotifySyncMarker(storage.BrainDir, memoryNotifySyncMarker{LastSyncAt: now}); err != nil {
114				return err
115			}
116			claimed = true
117			return nil
118		}); err != nil {
119			fmt.Fprintf(errW, "memory notify: hosted sync throttle: %v\n", err)
120			return false
121		}
122		if !claimed {
123			return false
124		}
125	
126		if branch == "" {
127			branch = hostedSyncBranch(ctx, opts.Runner, repoDir)
128		}
129		syncBranches := []string{branch}
130		if branch != distillDefaultBranch {
131			syncBranches = append(syncBranches, distillDefaultBranch)
132		}
133		for _, syncBranch := range syncBranches {
134			if err := notifyHostedFactsSync(ctx, errW, opts, repoDir, storage, syncBranch); err != nil {
135				fmt.Fprintf(errW, "memory notify: hosted fact sync failed (local brain unaffected): %v\n", err)
136			}
137		}
138		return true
139	}
140	
141	func memoryNotifySyncMarkerPath(brainDir string) string {
142		return filepath.Join(brainDir, memoryNotifySyncMarkerName)
143	}
144	
145	// readMemoryNotifySyncMarker treats a missing or unreadable marker as "never
146	// synced": the worst outcome of a corrupt marker is one extra sync.
147	func readMemoryNotifySyncMarker(brainDir string) memoryNotifySyncMarker {
148		var marker memoryNotifySyncMarker
149		data, err := os.ReadFile(memoryNotifySyncMarkerPath(brainDir))
150		if err != nil {
151			return memoryNotifySyncMarker{}
152		}
153		if err := json.Unmarshal(data, &marker); err != nil {
154			return memoryNotifySyncMarker{}
155		}
156		return marker
157	}
158	
159	func writeMemoryNotifySyncMarker(brainDir string, marker memoryNotifySyncMarker) error {
160		data, err := json.Marshal(marker)
161		if err != nil {
162			return err
163		}
164		return os.WriteFile(memoryNotifySyncMarkerPath(brainDir), data, 0o600)
165	}

