package brainnotify

import (
	"slices"
	"testing"

	"github.com/stretchr/testify/require"
)

func captureSpawns(t *testing.T) (*string, *[]string, *int) {
	t.Helper()
	original := spawnDetached
	t.Cleanup(func() { spawnDetached = original })
	var dir string
	var args []string
	spawned := 0
	spawnDetached = func(d string, a ...string) {
		dir = d
		args = slices.Clone(a)
		spawned++
	}
	return &dir, &args, &spawned
}

func TestNotifyPushSpawnsContentFreeBrainHint(t *testing.T) {
	t.Setenv(memoryWorkerOriginEnv, "")
	gotDir, gotArgs, _ := captureSpawns(t)

	NotifyPush("/repo", "feature/memory")

	require.Equal(t, "/repo", *gotDir)
	require.Equal(t, []string{
		"brain", "memory", "notify",
		"--event", "push",
		"--branch", "feature/memory",
	}, *gotArgs)
	require.NotContains(t, *gotArgs, "--repo-key", "Brain remains the repository identity authority")
	require.NotContains(t, *gotArgs, "--session", "a push hint has no single session")
}

func TestNotifyPushOmitsUnknownBranch(t *testing.T) {
	t.Setenv(memoryWorkerOriginEnv, "")
	_, gotArgs, _ := captureSpawns(t)

	NotifyPush("/repo", "")

	require.Equal(t, []string{"brain", "memory", "notify", "--event", "push"}, *gotArgs)
}

func TestNotifyPushTrimsRoutingValues(t *testing.T) {
	t.Setenv(memoryWorkerOriginEnv, "")
	gotDir, gotArgs, _ := captureSpawns(t)

	NotifyPush(" /repo ", " main ")

	require.Equal(t, "/repo", *gotDir)
	require.Equal(t, []string{"brain", "memory", "notify", "--event", "push", "--branch", "main"}, *gotArgs)
}

func TestNotifyPushSkipsInvalidOrRecursiveHints(t *testing.T) {
	_, _, spawned := captureSpawns(t)

	t.Run("empty repository root", func(t *testing.T) {
		t.Setenv(memoryWorkerOriginEnv, "")
		NotifyPush("", "main")
	})
	t.Run("memory worker origin", func(t *testing.T) {
		t.Setenv(memoryWorkerOriginEnv, "1")
		NotifyPush("/repo", "main")
	})

	require.Zero(t, *spawned)
}
