23	// memoryNotifySyncMarkerName is the brain-relative marker recording the last
24	// push-hint sync. Shared by every notify process; read and claimed under the
25	// brain write lock so concurrent hints race safely.
26	const memoryNotifySyncMarkerName = "hosted_sync_notify.json"
27	
28	// notifyHostedFactsSync is a test seam over hostedFactsSyncAndPull.
29	var notifyHostedFactsSync = hostedFactsSyncAndPull
30	
31	// memoryPushWorkLaunch spawns `memory push-work` detached, the same shape as
32	// memoryWorkerLaunch: `memory notify` is a fast content-free hint and must
33	// never carry the upload's network round trips inline — a host adapter may
34	// invoke it synchronously. The child runs with the worker-origin environment
35	// so nothing it shells out to re-notifies. Injectable for tests; a launch
36	// failure never fails the host.
37	var memoryPushWorkLaunch = func(repoDir, branch string) error {
38		exe, err := os.Executable()
39		if err != nil {
40			return err
41		}
42		args := []string{"memory", "push-work"}
43		if branch != "" {
44			args = append(args, "--branch", branch)
45		}
46		command := exec.Command(exe, args...)
47		command.Dir = repoDir
48		command.Env = memoryWorkerChildEnvironment(os.Environ(), repoDir)
49		command.Stdout = nil
50		command.Stderr = nil
