101	// hint, so nothing here may fail the caller — every outcome is reported on
102	// errW and swallowed. The return value says whether the work ran, for tests
103	// and for the caller's log line only.
104	func hostedSyncOnPushHint(ctx context.Context, errW io.Writer, opts Options, repoDir string, storage repoStorage, branch string) bool {
105		claimed := false
106		if err := withBrainWriteLock(storage.BrainDir, func() error {
107			now := opts.Now().UTC()
108			marker := readMemoryNotifySyncMarker(storage.BrainDir)
109			if now.Sub(marker.LastSyncAt) < memoryNotifyHostedSyncMinInterval {
110				return nil
111			}
112			if err := writeMemoryNotifySyncMarker(storage.BrainDir, memoryNotifySyncMarker{LastSyncAt: now}); err != nil {
113				return err
114			}
115			claimed = true
116			return nil
117		}); err != nil {
