144	// readMemoryNotifySyncMarker treats a missing or unreadable marker as "never
145	// synced": the worst outcome of a corrupt marker is one extra sync.
146	func readMemoryNotifySyncMarker(brainDir string) memoryNotifySyncMarker {
147		var marker memoryNotifySyncMarker
148		data, err := os.ReadFile(memoryNotifySyncMarkerPath(brainDir))
149		if err != nil {
150			return memoryNotifySyncMarker{}
151		}
152		if err := json.Unmarshal(data, &marker); err != nil {
153			return memoryNotifySyncMarker{}
154		}
155		return marker
156	}
