13	// hostedPlacement is the slice of the host CLI's `entire repo view --json`
14	// output this plugin needs (entireio/cli#2758): the repo's region-local ULID
15	// and its cell API base URL, both top-level fields.
16	type hostedPlacement struct {
17		RepoID string `json:"repoId"`
18		APIURL string `json:"apiUrl"`
19	}
20	
21	type connectOptions struct {
22		repoID string
23		apiURL string
24	}
