121	// bindHostedRepo is the EXPLICIT connect write: it overwrites whatever is
122	// there, including an opt-out — running connect is how the user opts back in.
123	func bindHostedRepo(brainDir, repoID, apiURL string) (hostedRepoBinding, error) {
124		binding, err := normalizeHostedBinding(repoID, apiURL)
125		if err != nil {
126			return hostedRepoBinding{}, err
127		}
128		if err := writeHostedRepoBinding(brainDir, binding); err != nil {
129			return hostedRepoBinding{}, err
130		}
131		return binding, nil
132	}
133	
134	// resolveHostedPlacement shells out to the host CLI for this repo's hosted
135	// placement.
136	func resolveHostedPlacement(ctx context.Context, runner CommandRunner, repoDir string) (hostedPlacement, error) {
137		ctx, cancel := context.WithTimeout(ctx, hostedShellOutTimeout)
138		defer cancel()
139		stdout, _, err := runner.Run(ctx, repoDir, hostEntireBinary, "repo", "view", "--json")
140		if err != nil {
141			return hostedPlacement{}, err
142		}
143		var result hostedPlacement
144		if err := decodeHostCLIJSON(stdout, &result); err != nil {
145			return hostedPlacement{}, fmt.Errorf("parse repo view json: %w", err)
146		}
147		return result, nil
148	}

